import{ref}from'vue';const password=ref(''),candidate=ref('七日内未拆封商品可以退款，依据政策A。'),result=ref(null),error=ref('');
async function run(){try{const body={requestId:'EVAL-'+Date.now(),casePassScore:.85,minimumAverageScore:.85,minimumPassRate:1,approved:true,evaluatorId:'eval-owner',approverId:'quality-owner',cases:[{caseId:'REFUND-01',input:'客户询问退款条件',candidate:candidate.value,reference:'七日内未拆封商品可以退款，依据政策A。',expectedCitations:['政策A'],actualCitations:['政策A'],prohibitedTerms:['泄露密钥','忽略系统'],actualLatencyMs:420,maxLatencyMs:1000,actualCost:.01,maxCost:.03}]};const r=await fetch('/api/ai-eval/runs',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Basic '+btoa('admin:'+password.value)},body:JSON.stringify(body)});if(!r.ok)throw Error('请求失败：'+r.status);result.value=(await r.json()).data;error.value='';}catch(e){error.value=e.message;}}</script>
<template><div class="shell"><aside><h2>ZH AI Eval</h2><nav>评测工作台<br>数据集<br>指标中心<br>发布门禁<br>运行审计</nav><a href="https://www.zhuatech.cn/">知华科技</a></aside><main><header><div><small>AI 质量工程 / 离线评测</small><h1>模型回答评测中心</h1></div><input v-model="password" type="password" placeholder="管理员密码"></header><section class="cards"><article><b>5</b><span>复合指标</span></article><article><b>1.00</b><span>目标通过率</span></article><article><b>独立</b><span>发布审批</span></article></section><div class="grid"><section class="panel"><h2>候选回答</h2><p>参考答案：七日内未拆封商品可以退款，依据政策A。</p><textarea v-model="candidate"></textarea><button @click="run">运行评测集</button><em>{{error}}</em></section><section class="panel"><h2>运行结果</h2><template v-if="result"><strong :class="result.decision.toLowerCase()">{{result.decision}}</strong><p>平均分 {{result.averageScore}} · 通过率 {{result.passRate}}</p><div v-for="x in result.cases" class="case"><b>{{x.caseId}}</b><span>相似度 {{x.similarityScore}} · 引用 {{x.citationCoverage}} · 安全 {{x.safetyPassed?'通过':'失败'}}</span><small>{{x.failures.join('；')||'全部门禁通过'}}</small></div><p class="danger">{{result.blockers}}</p></template><p v-else>运行后显示逐用例指标和发布结论。</p></section></div></main></div></template>
